/**
 * Reverses a string.
 * 
 * @param {string} str - The string to reverse.
 * @returns {string} The reversed string.
 */
function reverseString(str) {
  return str.split('').reverse().join('');
}

// Example usage
console.log(reverseString("stressed")); 
// Output: "edresst"
```

